import { createDebateCatalog, choice, reply, ignore, finishBranches } from "./kanab-quest-social-debate-builder";
import type { KqSocialPlatform } from "./kanab-quest-social-types";

const { add, replyBranches, scenarios, narratives } = createDebateCatalog();
type DraftChoice = ReturnType<typeof choice>;
type CommunityArc = {
  id: string; platform: KqSocialPlatform; name: string; title: string; body: string;
  opening: Record<string, DraftChoice>; contexts: Record<string, string>;
  responseTitle: string; responseBody: string; sharp: DraftChoice; explain: DraftChoice; ignored: string;
  endTitle: string; endBody: string; ending: Record<string, DraftChoice>;
  consequences: Parameters<typeof finishBranches>[0];
};

function addArc(arc: CommunityArc) {
  const openingId = `${arc.id}-post`, responseId = `${arc.id}-reply`;
  const common = { requirement: "general" as const, arc: arc.name,
    audience: "Les habitués, des curieux et des lecteurs qui te contredisent", character: "Ton compte de producteur CBD" };
  add(openingId, arc.platform, 1, { ...common, title: arc.title, body: arc.body,
    image: "workshop", choices: arc.opening });
  add(responseId, arc.platform, 2, { ...common, title: arc.responseTitle, body: arc.responseBody,
    image: "workshop", replyTo: { scenarioId: openingId, commentIndex: 0 },
    choices: { sharp: arc.sharp, explain: arc.explain, ignore: ignore(arc.ignored) },
    continuations: replyBranches(openingId, arc.contexts) }, openingId);
  add(`${arc.id}-after`, arc.platform, 3, { ...common, title: arc.endTitle, body: arc.endBody,
    image: "community", choices: arc.ending, continuations: finishBranches(arc.consequences, arc.ending) }, responseId);
}

addArc({
  id: "ig-debate-review", platform: "instagram", name: "Un avis n’est pas une enquête",
  title: "Une mauvaise expérience mérite mieux qu’une bagarre",
  body: "Tu veux parler des avis sur les fleurs CBD. Une personne peut être déçue sans mentir ; un compte qui commente ton travail n’est pas forcément ton client. Ta manière d’accueillir les critiques peut rassurer les lecteurs ou leur donner envie de garder leurs déceptions pour eux.",
  opening: {
    listen: choice("Accueillir les déceptions précises", "Tu demandes du contexte sans transformer le client en accusé.", "craft",
      "Une fleur peut décevoir : odeur, conservation, attentes différentes… Un avis précis aide davantage que cinq étoiles automatiques. Dis ce qui t’a déplu ; si ça concerne un achat, garde tes coordonnées et ta référence de commande en message privé.",
      "La demande de contexte ouvre un échange concret. Max y voit déjà une manière de trier les critiques ; les autres lecteurs attendent de voir comment tu lui réponds.",
      ["skeptic", "Traduction : si l’avis vous plaît pas, vous demandez un dossier pour l’enterrer."], ["visitor", "Je peux dire que je n’ai pas aimé sans me faire expliquer que je n’y connais rien ?"]),
    challenge: choice("Viser les jugements sans contexte", "Tu distingues le témoignage d’un procès lancé sous une photo.", "reach",
      "« Tous les producteurs vendent du foin », ce n’est pas un avis sur un achat, c’est un raccourci. Critiquez une expérience, un produit, une réponse. Juger toute une profession depuis trois commentaires, c’est pratique, mais ça n’explique rien.",
      "La formule attire des lecteurs lassés des attaques générales. D’autres entendent surtout un producteur sur la défensive, et Max s’engouffre dans cette lecture.",
      ["skeptic", "Vous adorez les avis jusqu’au jour où ils disent que votre boulot vaut rien."], ["ines", "Je suis d’accord sur les raccourcis, mais un client fâché ne va pas forcément choisir les bons mots."]),
    simple: choice("Laisser une place aux goûts", "Tu rappelles qu’un désaccord de goût peut rester un désaccord.", "care",
      "Vous avez le droit de ne pas aimer une fleur CBD. On peut parler des attentes et de ce qui a déçu sans chercher à gagner. Un avis de goût ne devient pas plus vrai parce qu’il est enthousiaste, ni moins valable parce qu’il est négatif.",
      "Les habitués apprécient la place laissée aux préférences. Max ramène tout de même la discussion à la façon dont les vendeurs traiteraient les critiques.",
      ["skeptic", "Beau discours. Dès qu’un avis est négatif, vous sortez le couplet du faux client."], ["jade", "Distinguer un goût d’un défaut, ça demande d’écouter avant de répondre."]),
  },
  contexts: { listen: "Max soupçonne une procédure destinée à faire taire les gens. Lou pose, elle, une vraie question.", challenge: "Ton ton ferme a amené Max sur le terrain de la confiance, pas sur celui d’un achat identifiable.", simple: "Max accuse les vendeurs en général. Tu n’as ni commande ni échange privé permettant de qualifier son commentaire de faux avis." },
  responseTitle: "« Vous enterrez les mauvais avis »", responseBody: "Max t’accuse de filtrer les critiques. Son commentaire est visible sous ton post ; tu peux répondre sur ta façon d’écouter ou laisser cette accusation sans réponse.",
  sharp: reply("Lui renvoyer son procès d’intention", "Tu attaques sa manière d’accuser sans exemple.", "reach",
    "Tu as déjà le verdict, il ne te manque que les faits. Un commentaire sans contexte ne devient pas une enquête parce que tu prends un ton de procureur. Si tu as une expérience précise, raconte-la.",
    "Max reprend le mot « procureur » et la discussion se déplace vers ton ton. Des lecteurs trouvent la réplique méritée ; Lou ne sait toujours pas comment tu accueillerais sa déception.",
    ["skeptic", "Voilà, il faut juste une critique et le vendeur s’énerve. Merci pour la démonstration."], ["visitor", "Je demandais surtout si on pouvait ne pas aimer sans se faire rentrer dedans."]),
  explain: reply("Distinguer écoute et vérification", "Tu reconnais la critique possible sans annoncer une vérification inexistante.", "craft",
    "Un avis négatif peut être juste. Je ne sais pas si tu parles d’un achat précis : rien ici ne permet de le vérifier. Demander le contexte sert à comprendre, pas à exiger un avis positif. Et une référence de commande reste en privé, jamais affichée pour te mettre la pression.",
    "Lou voit mieux la différence entre discuter d’un goût et traiter un problème d’achat. Max reste sceptique ; tu n’as ni prétendu l’avoir identifié ni effacé sa remarque.",
    ["visitor", "D’accord : je peux expliquer ma déception ici et garder le numéro de commande pour le privé."], ["skeptic", "Ça reste votre parole. On verra surtout comment vous répondez quand ça arrive."]),
  ignored: "Tu laisses le commentaire en place sans répondre. La question de Lou reste ouverte ; tu gardes ton énergie, mais personne ne peut déduire de ton silence comment tu traiterais un avis négatif.",
  endTitle: "Quelle place pour les prochaines critiques ?", endBody: "Tu peux consacrer une nouvelle publication aux retours clients, repartir au conflit ou refermer le sujet. Le commentaire de Max n’a fourni aucune preuve d’un achat.",
  ending: {
    challenge: choice("Défier les jugements expéditifs", "Tu fais du procès d’intention le sujet du nouveau post.", "reach", "Un avis peut être dur et utile. Une accusation vague peut être polie et ne rien apporter. Je préfère une critique précise à une distribution de bons et de mauvais points sur toute la profession.", "Le post prolonge le débat sur la crédibilité des critiques. La fermeté plaît à certains, tandis que d’autres craignent une nouvelle bataille à chaque remarque.", ["skeptic", "Encore un post pour expliquer quelles critiques tu acceptes."], ["sam", "La précision compte. Attention à ne pas en faire une barrière contre les gens qui s’expriment maladroitement."]),
    document: choice("Décrire comment écouter un retour", "Tu rends ton engagement concret sans inventer de dossier traité.", "craft", "Pour parler d’un retour : ce qui était attendu, ce qui a été constaté, puis ce qu’on peut vérifier. Aucun numéro de commande en public. Un problème d’achat mérite un échange ; un goût différent n’a pas besoin d’un vainqueur.", "Lou comprend mieux comment faire un retour. Max reste méfiant : cette méthode devra tenir aussi le jour où le commentaire sera franchement désagréable.", ["jade", "Ça laisse une place à un défaut réel comme à une préférence personnelle."], ["visitor", "Je comprends mieux où raconter le problème et où garder mes informations."]),
    refocus: choice("Refermer sans distribuer de verdict", "Tu gardes le commentaire visible et passes à autre chose.", "care", "Je garde les désaccords visibles et je ferme ce sujet pour aujourd’hui. On peut ne pas aimer une fleur ou une façon de communiquer. Ça ne nous oblige pas à faire de chaque commentaire un procès.", "Le fil perd de sa tension. Max n’a pas retiré son accusation ; les habitués, eux, peuvent passer à autre chose sans lui demander son accord.", ["ines", "On peut laisser la discussion là sans décider qui a gagné."], ["noe", "Et le prochain avis se lira pour ce qu’il raconte, pas comme la revanche de celui-ci."]),
  },
  consequences: {
    sharp: { body: "Ta réplique sur le procureur a braqué Max et laissé Lou sans réponse sur le fond. Le prochain post peut réparer ce manque ou prolonger la confrontation.", lead: "J’ai répondu sèchement au procès d’intention. Je reviens à la question de départ : quelle place laisser aux retours négatifs ?" },
    explain: { body: "Tu as expliqué la différence entre accueillir une critique et vérifier un achat. Max n’est pas convaincu, mais Lou a compris où garder ses informations privées.", lead: "J’ai précisé pourquoi le contexte d’un retour compte. Ça ne permet pas de déclarer un avis faux simplement parce qu’il dérange." },
    ignore: { body: "Tu n’as pas répondu à Max. La question de Lou reste visible ; un nouveau post peut donner tes repères, sans prétendre que la conversation précédente a été réglée.", lead: "Je n’ai pas répondu au commentaire précédent. La question des retours mérite tout de même mieux que notre affrontement." },
  },
});

addArc({
  id: "ig-debate-origin", platform: "instagram", name: "L’origine ne se devine pas sur une photo",
  title: "« Producteur » n’est pas une preuve imprimée", body: "Sur les réseaux, une photo de fleurs devient vite une preuve d’origine pour les uns, une preuve d’importation pour les autres. Tu veux parler de traçabilité, mais les lecteurs risquent de prendre le moindre mot comme une affirmation sur ton propre compte.",
  opening: {
    trace: choice("Parler de traçabilité", "Tu sépares image, déclaration et document vérifiable.", "craft", "Une belle photo ne prouve ni le pays de culture ni l’identité du cultivateur. Une origine se documente : qui a produit, quel lot, quelles informations permettent de le relier au produit vendu. Le décor et les drapeaux ne remplacent pas ces réponses.", "Le post met l’accent sur les éléments vérifiables. Max transforme aussitôt cette exigence en accusation visant ton propre compte.", ["skeptic", "Vous dites tous ça. Derrière, c’est le même grossiste étranger avec une étiquette locale."], ["visitor", "Je ne savais pas ce qu’il fallait regarder à part les mentions sur le sachet."]),
    slogan: choice("Bousculer le marketing du terroir", "Tu critiques les étiquettes qui racontent plus que ce qu’elles prouvent.", "reach", "Un drapeau sur un sachet ne fait pas pousser la fleur ici. Quand une marque dit « local », la vraie question est simple : qu’est-ce qui est local, la culture, le conditionnement ou le siège du vendeur ?", "La question est facile à relayer. Des lecteurs veulent l’appliquer à toutes les boutiques ; Max s’en sert pour t’accuser sans présenter de lot.", ["skeptic", "Et toi, tu changes juste l’étiquette avant de nous faire le discours du petit producteur ?"], ["sam", "Poser la question n’autorise pas à répondre au hasard pour une boutique qu’on n’a pas vérifiée."]),
    ask: choice("Inviter à poser une seule question", "Tu proposes un repère simple sans distribuer de labels.", "care", "Avant de conclure sur l’origine d’une fleur, demandez de quelle étape on parle. Cultiver, transformer, conditionner et revendre sont des métiers différents. Les expliquer clairement vaut mieux qu’un mot « artisanal » laissé tout seul.", "Quelques lecteurs retiennent la distinction entre les métiers. Max y entend une manière de justifier la revente, et sa remarque arrive sous ton post.", ["skeptic", "La différence, c’est surtout le prix que vous rajoutez sur une fleur achetée ailleurs."], ["ines", "Dire ce qu’on fait soi-même, ce serait déjà une base claire."]),
  },
  contexts: { trace: "Max parle d’un grossiste sans identifier de lot ni de document. Tu peux contester son raisonnement sans inventer une preuve qui n’est pas affichée.", slogan: "Ta pique sur les étiquettes est maintenant retournée contre toi. Le fil ne contient pas les éléments permettant de trancher l’origine d’un produit.", ask: "Max mélange la question de l’origine avec celle de la marge. Tu peux distinguer les sujets ou le laisser commenter." },
  responseTitle: "« Tu changes juste l’étiquette »", responseBody: "Max accuse ton compte de maquiller une origine. La réponse doit rester à la hauteur de ce qui est réellement connu dans le fil.",
  sharp: reply("Lui demander sa boule de cristal", "Tu tournes son accusation sans preuve en dérision.", "reach", "Impressionnant, tu retrouves un fournisseur à travers une photo. Ta boule de cristal donne aussi les numéros de lot ? Une accusation mérite mieux qu’une intuition emballée en certitude.", "Max relève la moquerie et réclame que tu publies tes documents. Les lecteurs regardent désormais si l’ironie cachait un manque de réponse.", ["skeptic", "La blague est jolie. Les preuves, elles sont où ?"], ["jade", "Il accuse sans élément, oui. Mais l’ironie ne renseigne pas davantage sur une origine."]),
  explain: reply("Séparer accusation et preuve", "Tu dis ce qui permettrait de vérifier, sans annoncer un document absent.", "craft", "Tu affirmes une origine que ce fil ne permet pas d’établir. Une photo ne prouve ni une culture locale ni une importation. Pour vérifier un produit, il faut relier un lot à des informations d’origine. Si on parle d’un achat précis, la question doit porter sur son lot, pas sur l’allure d’un compte.", "La réponse rend explicite la limite des informations disponibles. Max peut rester méfiant, tandis que Lou comprend pourquoi l’image seule ne tranche pas.", ["visitor", "Je retiens surtout qu’il faut pouvoir relier le document à ce qu’on achète."], ["skeptic", "Donc je demande les éléments sur le lot concerné. Pas juste une photo d’un champ."]),
  ignored: "Tu ne réponds pas à l’accusation. Elle reste visible sous ton post ; aucune origine n’a été démontrée ni réfutée par ton silence.",
  endTitle: "Ce qu’on peut montrer, ce qu’on ne peut pas déduire", endBody: "La discussion a glissé de l’origine des fleurs à ta crédibilité personnelle. Tu peux remettre les critères au centre, durcir le ton ou arrêter de nourrir la dispute.",
  ending: {
    challenge: choice("Contester les certitudes des deux camps", "Tu mets en cause les étiquettes flatteuses comme les accusations gratuites.", "reach", "Croire « local » sur un décor, c’est trop court. Créer une origine étrangère dans un commentaire, aussi. Si on demande des preuves aux vendeurs, on peut également demander des éléments à ceux qui accusent.", "La position provoque une nouvelle discussion sur la charge de la preuve. Certains apprécient la symétrie ; d’autres y voient encore une esquive.", ["skeptic", "Le vendeur fait la promesse, donc c’est à lui de l’étayer."], ["sam", "Oui. Et contester une promesse ne donne pas le pouvoir d’inventer l’origine inverse."]),
    document: choice("Définir une présentation vérifiable", "Tu expliques comment une origine doit être décrite et reliée au produit.", "craft", "Une présentation claire distingue producteur, transformateur et revendeur, puis indique à quel produit les informations se rapportent. Si une pièce manque, on le dit. Publier un papier sans lien avec le lot ne règle pas la question.", "Les lecteurs disposent de critères plus précis que l’apparence d’un compte. Max peut encore demander des éléments, mais la discussion a maintenant un objet plus précis que l’apparence de ton compte.", ["jade", "Le lien avec le produit évite de brandir n’importe quelle analyse comme un passeport."], ["visitor", "Et si ce lien n’est pas disponible, je sais que l’information reste à vérifier."]),
    refocus: choice("Laisser la question ouverte", "Tu refermes la dispute sans fabriquer de certificat de bonne conduite.", "care", "Je laisse ce rappel ici : une origine se documente, elle ne se devine pas au ton d’un compte. La discussion peut s’arrêter sans qu’on transforme une hypothèse en fait.", "Le sujet reste ouvert sur le fond et le ton retombe. Personne n’a gagné un label d’origine grâce à la dernière phrase.", ["ines", "On peut garder une question en suspens sans remplir le vide avec une accusation."], ["noe", "Un document lié au bon produit sera plus utile qu’un dernier mot."]),
  },
  consequences: {
    sharp: { body: "Ta blague sur la boule de cristal a attiré des répliques, pas des documents. Pour la suite, tu peux revenir aux critères ou repartir au duel.", lead: "J’ai répondu par une moquerie à une accusation. Ça n’a produit aucune preuve d’origine ; voici le point que je veux garder." },
    explain: { body: "Tu as distingué les faits manquants de l’accusation. Max réclame des éléments sur le produit concerné ; cette demande reste différente d’une preuve que tu aurais déjà fournie.", lead: "J’ai expliqué ce que le fil permettait de savoir, et surtout ce qu’il ne permettait pas de conclure." },
    ignore: { body: "Tu n’as pas répondu à l’accusation d’importation. Aucun lecteur n’a reçu d’explication de ta part ; le nouveau post peut poser tes critères sans annoncer que Max s’est rétracté.", lead: "Je n’ai pas répondu au commentaire sur l’origine. Je préfère poser la question des origines clairement plutôt que laisser chaque photo servir de preuve à tout et à son contraire." },
  },
});

addArc({
  id: "ig-debate-health", platform: "instagram", name: "Le témoignage qui devient une promesse",
  title: "Une expérience personnelle n’est pas une garantie", body: "Tu veux parler de la façon dont les témoignages sont repris pour vendre du CBD. Certains lecteurs décrivent une expérience ; d’autres attendent une promesse de soin. Ton post peut poser une limite claire sans juger le vécu de quelqu’un.",
  opening: {
    limits: choice("Poser la limite des témoignages", "Tu accueilles les expériences sans les transformer en promesses médicales.", "craft", "Un témoignage raconte ce qu’une personne a vécu. Il ne suffit pas à promettre qu’une fleur CBD traitera le problème d’une autre. Sur ce compte, pas de diagnostic en commentaire, pas de résultat médical garanti et pas de conseil pour remplacer un traitement.", "La limite rassure certains lecteurs. Lou la présente comme un aveu d’inutilité, alors qu’une personne demande surtout comment raconter son propre vécu.", ["visitor", "Donc tu vends un truc et tu refuses de dire à quoi ça sert. Pratique."], ["ines", "Je peux raconter mon expérience sans que ça devienne une publicité promettant la même chose à tout le monde ?"]),
    miracle: choice("Critiquer les vendeurs de miracles", "Tu attaques la surenchère des promesses, sans viser une boutique réelle.", "reach", "Quand une publicité promet de régler toutes les nuits, toutes les douleurs et tous les soucis avec le même produit, la prudence disparaît derrière la vente. Le CBD n’a pas besoin qu’on lui invente une promesse universelle.", "Le propos est partagé dans la discussion comme une critique des promesses excessives. Lou réduit ta nuance à une contradiction commerciale.", ["visitor", "Les autres exagèrent et toi tu vends du vent avec des phrases prudentes, c’est ça ?"], ["jade", "On peut critiquer une promesse sans nier ce qu’une personne dit avoir ressenti."]),
    space: choice("Garder un espace de témoignage", "Tu proposes d’écouter sans faire du fil une consultation.", "care", "Vous pouvez parler de vos attentes et de vos déceptions ici. Je ne vais pas déduire une solution médicale de vos commentaires. Le vécu mérite d’être entendu sans servir automatiquement d’argument de vente.", "Le post laisse une place aux expériences différentes. Lou demande une réponse binaire que ton message ne proposait pas.", ["visitor", "Ça marche ou ça marche pas ? Vous évitez toujours la réponse dès qu’on insiste."], ["ines", "J’aime pouvoir lire des expériences sans qu’on me promette un résultat à leur place."]),
  },
  contexts: { limits: "Lou transforme une limite de communication en verdict sur le produit. La question d’Inès appelle une distinction, pas une promesse en retour.", miracle: "Lou te pousse à défendre ton commerce en garantissant quelque chose. Répondre ne t’oblige pas à promettre un effet médical.", space: "Lou veut une réponse valable pour tout le monde. Tu peux refuser ce raccourci sans nier les expériences individuelles." },
  responseTitle: "« Alors ça marche ou pas ? »", responseBody: "Lou confond prudence et absence d’intérêt. Tu peux le recadrer, préciser ta limite ou laisser son commentaire sans réponse.",
  sharp: reply("Refuser son ultimatum", "Tu t’attaques au raisonnement binaire de Lou.", "reach", "Ton questionnaire à deux cases ne transforme pas un commentaire en consultation. Si tu veux une promesse magique pour tout le monde, tu ne l’auras pas ici. Et non, la nuance n’est pas un aveu que tu viens de m’arracher.", "Lou se braque sur le ton et la discussion prend la forme d’un affrontement. La limite reste présente, mais Inès peine à savoir si elle peut encore raconter son expérience tranquillement.", ["visitor", "Beaucoup de mots pour éviter ma question, comme prévu."], ["ines", "Je comprends la limite. La façon de répondre donne moins envie de poser une question maladroite."]),
  explain: reply("Répondre sans promettre un soin", "Tu distingues intérêt personnel, preuve et prise en charge médicale.", "craft", "Une personne peut avoir un intérêt pour le CBD ou raconter un ressenti. Ça ne m’autorise pas à promettre un résultat de santé pour toi. Un avis sous une publication ne me permet pas de savoir ce qui te conviendrait. Refuser une promesse universelle, ce n’est pas déclarer toutes les expériences fausses.", "Inès peut distinguer son témoignage d’une garantie commerciale. Lou ne donne pas son accord, mais la réponse n’a ajouté ni diagnostic ni conseil sur un traitement.", ["ines", "D’accord, je peux décrire ce que j’ai vécu sans affirmer que ça doit marcher pour quelqu’un d’autre."], ["visitor", "Au moins tu poses ta limite. Ça ne répond pas à toutes mes attentes, mais je vois ce que tu refuses de promettre."]),
  ignored: "Tu ne réponds pas à Lou. Sa demande reste visible ; ton silence n’ajoute ni promesse médicale ni explication à celles déjà présentes dans ton post.",
  endTitle: "Faire une place aux vécus sans vendre un résultat", endBody: "Le prochain post peut défendre tes limites, expliquer ta manière de lire les témoignages ou mettre le sujet en pause. Aucun commentaire ne permet de conclure sur la santé d’un lecteur.",
  ending: {
    challenge: choice("Dénoncer le besoin de promesses", "Tu contestes la pression commerciale qui pousse à garantir toujours plus.", "reach", "Exiger d’un vendeur une promesse de santé pour le croire, c’est récompenser celui qui promet le plus. Je préfère assumer une limite que transformer chaque expérience positive en argument valable pour tous.", "Le propos suscite des réactions sur la vente et la confiance. Il ne résout pas les attentes de chacun, et certains trouvent encore le ton défensif.", ["visitor", "La prudence ne doit pas devenir une formule qui évite toutes les questions."], ["sam", "Exact. On peut poser une limite et continuer à expliquer ce qu’on vend sans la franchir."]),
    document: choice("Distinguer les niveaux de discours", "Tu rends lisibles le témoignage, l’information et la promesse.", "craft", "« Voilà mon expérience », « voilà ce que permet d’établir une source » et « voilà ce que je te garantis » sont trois phrases différentes. Je veux les garder distinctes ici. Un témoignage n’est ni un diagnostic ni une autorisation de promettre un soin.", "Les lecteurs trouvent un repère pour lire le fil sans juger les personnes. Le post reste une règle de discussion, pas une recommandation médicale.", ["jade", "Ça évite de faire porter au témoignage une conclusion qu’il n’a pas donnée."], ["ines", "Je peux lire le vécu de quelqu’un sans prendre ça comme une garantie pour moi."]),
    refocus: choice("Refermer sans conclusion médicale", "Tu laisses la limite visible et cesses de relancer le débat.", "care", "Je garde cette limite : on peut partager un vécu sans décider ici de la santé d’un autre. Je ferme le débat pour aujourd’hui. Les commentaires n’ont pas transformé ce compte en consultation.", "La conversation se calme sans réponse universelle. Les témoignages restent des témoignages, et aucun lecteur n’est présenté comme guéri ou convaincu.", ["ines", "On peut en rester là sans donner tort à l’expérience de quelqu’un."], ["noe", "Une limite maintenue vaut mieux qu’une promesse lâchée pour finir la discussion."]),
  },
  consequences: {
    sharp: { body: "Ta réplique a préservé la limite médicale mais refroidi Inès. Le prochain post peut rendre cette limite plus accueillante, sans récompenser l’ultimatum de Lou.", lead: "J’ai répondu sèchement à une demande de réponse universelle. Je veux clarifier la limite sans prendre de haut les personnes qui racontent leur vécu." },
    explain: { body: "Tu as séparé intérêt, ressenti et promesse de santé. Lou n’en attendait pas moins qu’une certitude, mais Inès sait mieux comment participer sans faire une publicité médicale.", lead: "J’ai distingué un ressenti personnel d’un résultat qu’un vendeur prétend garantir." },
    ignore: { body: "Tu n’as pas répondu à Lou. Ton prochain message doit rester une nouvelle prise de parole, sans prétendre avoir déjà clarifié sa question dans une réponse.", lead: "Je n’ai pas répondu au commentaire qui demandait une certitude. Voici la limite que je veux maintenir dans mes publications." },
  },
});

addArc({
  id: "x-debate-quote", platform: "x", name: "La phrase qui voyage sans sa suite",
  title: "Une nuance de trop pour une capture", body: "Tu veux défendre le droit de ne pas aimer le CBD sans accepter les attaques contre tout le métier. Un post court peut exprimer cette nuance ; un lecteur peut aussi en isoler la phrase qui l’arrange.",
  opening: {
    nuance: choice("Dire que le CBD ne plaît pas à tous", "Tu sépares préférences et jugement global sur les producteurs.", "craft", "Certaines personnes n’aiment pas le CBD et n’y trouvent aucun intérêt. Ça ne rend pas leur goût illégitime, ni le travail des chanvriers ridicule. On peut refuser un produit sans résumer tout un métier à une arnaque.", "Max isole le début de ton message et lui fait dire que ton activité n’aurait aucun intérêt. Des lecteurs peuvent voir le raccourci, à condition de lire la suite.", ["skeptic", "« Aucun intérêt. » Même le producteur l’avoue. On peut fermer le dossier."], ["noe", "Tu as retiré « certaines personnes » et la phrase qui suit. Ce n’est plus le même propos."]),
    direct: choice("Défendre le droit de dire non", "Tu prends une position franche contre l’obligation de convaincre.", "reach", "Je n’ai pas besoin que tout le monde aime le CBD. Si ça ne vous intéresse pas, passez votre chemin : je ne vais pas vous fabriquer un besoin. Ça ne donne pas pour autant carte blanche pour insulter ceux qui en produisent.", "Le ton franc plaît à certains. Max retient « passez votre chemin » et présente ta limite comme un refus des critiques.", ["skeptic", "« Passez votre chemin. » Voilà comment les producteurs répondent aux critiques."], ["ines", "La phrase parle des gens qui ne sont pas intéressés. La critique et l’insulte arrivent après."]),
    short: choice("Garder une phrase d’accueil", "Tu reconnais les préférences sans lancer un duel.", "care", "Vous n’avez aucune obligation d’aimer le CBD. Ce compte parle d’un métier et de ce qu’il suscite, y compris des réserves. J’aimerais simplement qu’on puisse en discuter sans se mépriser.", "Le message est posé. Max le résume comme une demande de gentillesse obligatoire, ce qui change le sens de ta dernière phrase.", ["skeptic", "En résumé : pas de critiques, soyez gentils avec le vendeur."], ["visitor", "J’avais plutôt compris qu’on pouvait ne pas être d’accord sans se manquer de respect."]),
  },
  contexts: { nuance: "La citation de Max coupe le sujet de la phrase. Il ne suffit pas d’ajouter un ton plus fort pour rendre ton texte complet visible.", direct: "Max conserve ton impératif et retire ce à quoi il répondait. Tu peux remettre le contexte ou repartir au clash.", short: "Max reformule ton message en interdiction de critiquer. Il n’a pas cité une phrase où tu demandes cela." },
  responseTitle: "« Même le producteur l’avoue »", responseBody: "Une partie de ton post est reprise sous ton message. Tu peux contester la découpe directement, rétablir la nuance ou ne pas alimenter cette reprise.",
  sharp: reply("Dénoncer son découpage", "Tu fais de sa lecture de mauvaise foi le sujet de la réponse.", "reach", "Il manque des morceaux, mais tu as gardé toute ta certitude. Tu peux relire le post entier avant de distribuer les aveux ? On gagne du temps quand on répond à ce qui est écrit, pas à la version qu’on aurait préféré trouver.", "Max accuse ta réponse de condescendance et la dispute gagne une deuxième cible. Le texte complet reste là, mais les lecteurs regardent maintenant le duel.", ["skeptic", "Le fameux « tu n’as pas compris » quand la phrase gêne son auteur."], ["sam", "Tu as raison sur la découpe. Le ton va surtout lui donner une autre phrase à extraire."]),
  explain: reply("Remettre le sens du post", "Tu rappelles la distinction sans promettre d’atteindre tous les lecteurs de la reprise.", "craft", "Mon propos distingue trois choses : ne pas aimer le CBD, critiquer un produit et insulter un métier. La première est une préférence, la deuxième peut être utile, la troisième n’est pas un argument. Ta reprise efface cette distinction ; le post complet reste juste au-dessus.", "Les lecteurs du fil disposent d’une correction précise. Tu n’affirmes pas que chaque personne ayant vu la reprise a lu ta réponse, et Max garde sa lecture.", ["visitor", "Avec les trois points, je comprends la différence. La version courte de Max changeait le sens."], ["skeptic", "J’ai trouvé ton ton défensif. Mais oui, tu avais écrit plus que ma reprise."]),
  ignored: "Tu ne réponds pas à la reprise. Le post complet reste accessible dans ce fil ; cela ne garantit pas que ceux qui lisent le commentaire de Max le consulteront.",
  endTitle: "Corriger sans vivre dans les captures", endBody: "Tu peux reprendre le thème dans un nouveau post ou fermer la séquence. Aucune action ne permet de savoir que tous les lecteurs d’une reprise ont vu le texte entier.",
  ending: {
    challenge: choice("Montrer ce qu’une citation retire", "Tu fais du découpage le sujet d’une nouvelle prise de position.", "reach", "Une citation peut garder les mots et retirer le sens. Enlever à qui une phrase s’applique, ce n’est pas la raccourcir proprement. Je veux bien répondre à une critique ; je ne peux pas passer ma journée à devenir l’auteur de phrases que je n’ai pas dites.", "Le post redonne une place à ton argument, au prix d’une nouvelle exposition au conflit. Certains demandent encore un exemple plus court.", ["skeptic", "Et voilà un autre post sur les gens qui comprennent mal tes posts."], ["noe", "La question du contexte tient. Il faudra aussi choisir combien de temps tu veux lui consacrer."]),
    document: choice("Rendre la distinction facile à retrouver", "Tu écris un point clair que les lecteurs du compte peuvent consulter.", "craft", "Mon repère reste simple : les goûts sont libres, les critiques peuvent être utiles, les insultes n’apportent pas de preuve. Ce sont trois sujets différents. Ce message ne me permet pas de savoir qui a lu une ancienne reprise, mais il rend ma position accessible ici.", "La position est consultable sans fausse promesse de corriger tout le réseau. L’effort porte sur les lecteurs qui viennent chercher le contexte.", ["jade", "On peut renvoyer vers ce message sans reconstituer toute la dispute."], ["visitor", "C’est plus simple que de lire dix réponses pour deviner ce qui a été coupé."]),
    refocus: choice("Laisser le texte et sortir du duel", "Tu fermes l’échange en gardant tes messages visibles.", "care", "Mon texte reste visible. Je ne vais pas relancer chaque reprise pour avoir le dernier mot. On peut garder un désaccord sans faire de ce fil l’unique sujet du compte.", "Tu diminues ton implication sans faire disparaître la reprise. Les lecteurs conservent les éléments du fil, et le désaccord reste possible.", ["ines", "Je peux relire le post si je veux comprendre. Pas besoin d’un nouvel épisode chaque heure."], ["sam", "Tu reprends la main sur ton temps, pas sur ce que chacun racontera ensuite."]),
  },
  consequences: {
    sharp: { body: "Ta réponse a dénoncé la découpe, puis donné à Max une nouvelle phrase sur laquelle s’énerver. Le prochain post peut rendre le fond visible ou continuer le duel.", lead: "J’ai répondu sèchement à une reprise de mon texte. Je reviens au sens que je voulais donner au message." },
    explain: { body: "Tu as rétabli les trois distinctions dans le fil. Les lecteurs présents peuvent les consulter ; tu ne sais pas qui a vu la reprise ailleurs.", lead: "J’ai précisé mon propos dans la conversation. Je le remets ici pour ceux qui veulent le retrouver sans suivre tout l’échange." },
    ignore: { body: "Tu n’as pas répondu à la reprise de Max. Ce nouveau post peut exprimer ta position sans raconter une correction que tu n’as pas envoyée.", lead: "Je n’ai pas répondu à la reprise précédente. Voici ma position dans une nouvelle publication, sans prétendre qu’elle atteindra les mêmes lecteurs." },
  },
});

addArc({
  id: "x-debate-solidarity", platform: "x", name: "Solidaires sans parler d’une seule voix",
  title: "Défendre les chanvriers, sans effacer leurs désaccords", body: "Tu veux parler du métier et des difficultés communes. Les producteurs n’ont pourtant ni les mêmes charges, ni les mêmes pratiques, ni les mêmes priorités. Une publication solidaire peut reconnaître ces différences ou mettre une pression nouvelle sur ceux qui pensent autrement.",
  opening: {
    together: choice("Défendre un intérêt commun précis", "Tu proposes un accord limité, sans parler au nom de tout le métier.", "craft", "On peut demander des règles compréhensibles et des contrôles cohérents sans avoir le même avis sur tous les débouchés du chanvre. Je parle en mon nom. La solidarité entre producteurs commence mal si elle exige de signer une opinion unique.", "Des lecteurs apprécient cette limite. Sami y voit de la division et accuse les producteurs de ne jamais savoir ce qu’ils veulent.", ["sam", "Vous réclamez qu’on vous écoute et vous êtes même pas capables d’être d’accord entre vous."], ["jade", "Une demande commune peut tenir même si nos fermes et nos priorités sont différentes."]),
    sharp: choice("Refuser l’obligation de faire bloc", "Tu contredis ceux qui confondent soutien et silence.", "reach", "Soutenir les chanvriers ne devrait pas vouloir dire applaudir chaque discours du secteur. On peut défendre le droit de travailler et critiquer une promesse douteuse ou une pratique. Faire bloc n’oblige pas à fermer les yeux.", "Le message fait réagir sur la loyauté professionnelle. Sami l’interprète comme une attaque entre producteurs plutôt que comme une limite à la solidarité.", ["sam", "Le petit producteur qui tape sur les autres pour vendre son image de producteur propre, classique."], ["jade", "On peut discuter des pratiques sans distribuer des certificats de vertu à soi-même."]),
    local: choice("Inviter à comparer les contraintes", "Tu proposes d’écouter des réalités différentes sans conclure à une unanimité.", "care", "Avant de dire « les producteurs veulent », j’aimerais entendre de quels producteurs on parle. Les contraintes diffèrent. On peut commencer par écouter un désaccord précis, sans transformer celui qui le formule en traître au métier.", "Le post ouvre une place aux différences. Sami répond qu’un secteur divisé ne serait pas crédible, ce qui déplace la discussion vers l’image collective.", ["sam", "À force de nuancer, vous n’avez plus rien à défendre ensemble."], ["noe", "Ou on peut défendre quelque chose de précis, sans prétendre que tout le monde a signé."]),
  },
  contexts: { together: "Sami assimile désaccord et incohérence. Jade décrit pourtant un accord limité, pas une unanimité que le fil aurait démontrée.", sharp: "Sami te prête une stratégie commerciale. Tu peux répondre sur le fond sans attribuer des intentions à tous les autres producteurs.", local: "Sami juge la crédibilité du secteur, alors que ton post propose seulement de préciser qui parle et pour quoi." },
  responseTitle: "« Vous n’êtes même pas d’accord entre vous »", responseBody: "Sami utilise les désaccords du métier pour écarter ta demande. Tu peux lui répondre sans devenir le porte-parole de producteurs qui ne t’ont rien demandé.",
  sharp: reply("Lui renvoyer son exigence d’unanimité", "Tu ridiculises l’idée qu’un métier devrait penser comme un seul homme.", "reach", "Il faut combien de producteurs récitant la même phrase pour avoir le droit de parler, selon toi ? Un métier, ce n’est pas une chorale obligatoire. Tu peux discuter de la demande au lieu de compter ceux qui chantent exactement pareil.", "La réplique amuse certains lecteurs et crispe Sami. Le débat sur la demande commune se transforme en confrontation sur la façon dont tu réponds.", ["sam", "Toujours une bonne formule. Mais qui te suit réellement sur ta demande ?"], ["ines", "La question de qui parle reste utile, même si l’unanimité n’est pas une condition."]),
  explain: reply("Nommer l’accord et le désaccord", "Tu limites ta parole à ce que tu défends réellement.", "craft", "Je ne dis pas que tous les chanvriers sont d’accord. Je défends ici des règles lisibles et des contrôles cohérents. Quelqu’un peut partager cette demande et me contredire sur un autre sujet. Le désaccord n’efface pas la demande ; il empêche simplement de parler au nom de tout le monde.", "Sami conteste encore le caractère général de ta demande, mais Jade voit ce qu’elle pourrait partager. La discussion porte enfin sur quelque chose de précis.", ["jade", "Je peux discuter de cette demande précise sans signer toutes tes autres opinions."], ["sam", "Présenté comme ta demande, c’est au moins clair. Je la trouve encore trop générale."]),
  ignored: "Tu ne réponds pas à Sami. La critique reste visible ; ton silence ne transforme pas ta publication en position collective approuvée par d’autres producteurs.",
  endTitle: "Une demande commune, pas un chèque en blanc", endBody: "La discussion sur la solidarité reste ouverte. Tu peux préciser la demande qui t’importe, défendre le droit de contredire le secteur ou reprendre ton travail.",
  ending: {
    challenge: choice("Défendre le droit au désaccord", "Tu prends position contre la loyauté qui oblige à se taire.", "reach", "Si la solidarité exige qu’on laisse passer tous les raccourcis, elle devient fragile. Je veux défendre le métier sans demander aux autres de se taire, et sans recevoir l’ordre de me taire à mon tour.", "La prise de position garde de la visibilité et ravive les questions de loyauté. Elle peut aussi éloigner les lecteurs venus chercher une demande concrète.", ["sam", "Très bien pour le principe. On fait quoi de concret avec ça ?"], ["jade", "Le droit de critiquer doit aussi valoir quand la critique te vise."]),
    document: choice("Décrire une discussion utile", "Tu proposes de comparer les demandes, les désaccords et les points à vérifier.", "craft", "Pour une discussion entre producteurs : préciser la difficulté, nommer la demande, puis distinguer ce qui fait accord et ce qui reste contesté. Un désaccord visible vaut mieux qu’une unanimité annoncée à la place des autres.", "Jade y voit une façon de faire entendre les petites exploitations. D’autres producteurs gardent leurs réserves, sans être sommés de choisir un camp.", ["jade", "Ça permet d’entendre une petite exploitation sans la fondre dans une moyenne."], ["noe", "Et de savoir ce qu’on soutient réellement, pas seulement avec qui on apparaît sur une photo."]),
    refocus: choice("Rester à ta place", "Tu clos le fil en rappelant que tu exprimes ta propre position.", "care", "Je parle en mon nom, et je laisse les autres préciser leur position. Soutenir le métier ne me donne pas leur signature. On peut discuter, partager un point et continuer à se contredire sur le reste.", "La conversation se termine sans victoire de camp ni soutien fabriqué. Le message limite ton rôle et la pression de représenter tout un secteur.", ["ines", "On sait qui parle. Les autres peuvent répondre sans devoir démentir qu’ils t’auraient mandaté."], ["jade", "Une position personnelle claire se discute plus facilement qu’un « nous » extensible."]),
  },
  consequences: {
    sharp: { body: "La formule de la chorale a détourné le fil vers ta répartie. Sami demande qui te suit ; tu ne peux pas inventer des soutiens pour donner plus de poids à la suite.", lead: "J’ai répondu par une pique à l’exigence d’unanimité. Ma position n’en devient pas une parole collective." },
    explain: { body: "Tu as identifié ta demande et reconnu les désaccords possibles. La suite peut préciser une manière de discuter, sans annoncer que d’autres producteurs t’ont rejoint.", lead: "J’ai précisé ce que je défends personnellement. Partager un point ne signifie pas partager tous les avis." },
    ignore: { body: "Tu n’as pas répondu à Sami. La prochaine publication peut fixer ton périmètre sans prétendre que son objection a été levée.", lead: "Je n’ai pas répondu au commentaire sur nos désaccords. Je veux toutefois clarifier à quel titre je prends la parole ici." },
  },
});

addArc({
  id: "x-debate-sponsor", platform: "x", name: "Qui finance ta parole ?",
  title: "Parler de partenariats avant de promettre son indépendance", body: "Préparer des photos, écrire et répondre prend du temps. Un soutien commercial peut financer ce travail, mais il change aussi la façon dont les lecteurs te regardent. Tu veux parler de cette tension et des limites que tu poses aux marques.",
  opening: {
    disclose: choice("Dire ce qu’un lecteur doit pouvoir savoir", "Tu défends une mention visible et une distinction entre soutien et opinion.", "craft", "Si une publication est rémunérée, les lecteurs doivent pouvoir le comprendre clairement. Une marque qui finance un format n’achète pas automatiquement mon accord sur tous les sujets. Expliquer le lien commercial fait partie du message, pas d’une note qu’on espère invisible.", "Le principe attire des questions sur les compromis réels. Noé affirme qu’une parole financée est forcément une parole achetée.", ["noe", "Dès qu’une marque te paie, ton avis est acheté. Le reste, c’est de l’emballage."], ["visitor", "J’aimerais surtout voir la mention avant de prendre le post pour un conseil spontané."]),
    frank: choice("Contester le procès en pureté", "Tu défends le droit de financer du contenu en exposant le conflit possible.", "reach", "Produire du contenu prend du temps. Être payé ne rend pas automatiquement chaque phrase fausse ; cacher qui paie rend la confiance beaucoup plus difficile. On peut discuter d’un partenariat sans jouer à deviner les intérêts derrière chaque virgule.", "Le ton nourrit un débat sur la rémunération. Noé y voit une justification anticipée de complaisance envers les marques.", ["noe", "Belle préparation du terrain pour dire du bien du prochain payeur."], ["sam", "Le financement compte, mais il faut aussi regarder ce que la personne affirme et les limites qu’elle accepte."]),
    boundary: choice("Garder une limite simple", "Tu annonces un principe sans prétendre avoir négocié un contrat.", "care", "Mon principe pour une publication commerciale : dire qu’elle est commerciale. La mention doit se voir tout de suite, pas après trois clics. Et ma liberté de ton se jugera sur mes publications, pas seulement sur ce que je promets aujourd’hui.", "Le post distingue intention et fait accompli. Noé répond que personne ne mordra la main qui le nourrit.", ["noe", "On connaît : indépendant jusqu’au jour où il faut critiquer celui qui paie."], ["ines", "Au moins, le principe n’est pas présenté comme une preuve que tout se passe déjà parfaitement."]),
  },
  contexts: { disclose: "Noé traite le paiement comme une preuve suffisante de mensonge. Tu peux reconnaître le conflit possible sans prétendre qu’un contrat précis vient d’être conclu.", frank: "Noé soupçonne une complaisance future. Le fil n’établit ni paiement ni contenu commandé par une marque.", boundary: "Noé pose une vraie question sur les limites de l’indépendance, avec un ton accusateur. Répondre n’exige pas de garantir que toute pression sera simple à gérer." },
  responseTitle: "« Ton avis est acheté »", responseBody: "Noé accuse les publications rémunérées de rendre tout discours faux. Tu peux aborder le conflit d’intérêts ou répondre à l’attaque, sans fabriquer un sponsor pour illustrer ton propos.",
  sharp: reply("Refuser son verdict automatique", "Tu renvoies Noé à la différence entre soupçon et preuve.", "reach", "Donc tu sais déjà qui me dicte chaque phrase sans même savoir de quel contrat on parle. C’est pratique, un verdict qui se passe de faits. Tu peux critiquer ce que j’écris ; inventer un donneur d’ordres ne remplace pas un argument.", "Noé réplique que tu esquives la question du financement. Le conflit gagne en visibilité, tandis que Lou attend encore une réponse sur la façon de reconnaître un contenu commercial.", ["noe", "Je parle du principe. Tu évites juste de reconnaître que le payeur a un intérêt."], ["visitor", "Le lien commercial peut compter sans que je pense que chaque phrase est dictée."]),
  explain: reply("Reconnaître le conflit possible", "Tu expliques la transparence sans la présenter comme une garantie absolue.", "craft", "Une marque qui paie a un intérêt, et les lecteurs doivent le savoir. Le dire n’efface pas le conflit possible. Ça permet de lire le contenu avec cette information, de vérifier ce qu’il affirme et de juger mes limites sur pièces. Je préfère que cette question soit posée franchement plutôt qu’elle reste cachée derrière un post présenté comme spontané.", "Lou voit mieux à quoi sert la transparence et ce qu’elle ne garantit pas. Noé garde sa méfiance, sans que tu prétendes avoir prouvé une indépendance absolue.", ["visitor", "La mention ne règle pas tout, mais elle m’évite de prendre ça pour une recommandation sans intérêt commercial."], ["noe", "D’accord sur le conflit. Je jugerai surtout la liberté de critiquer quand il y aura quelque chose de concret."]),
  ignored: "Tu ne réponds pas à Noé. Le commentaire reste visible, et ton intention de transparence ne devient ni un contrat ni une preuve d’indépendance grâce à ce silence.",
  endTitle: "Des limites qui pourront être jugées sur pièces", endBody: "Tu peux consacrer un nouveau post à tes principes commerciaux ou fermer la discussion. La discussion sur tes principes ne remplace pas la mention commerciale sur une publication rémunérée.",
  ending: {
    challenge: choice("Refuser les accusations sans objet", "Tu défends le droit de discuter des faits plutôt que des intentions supposées.", "reach", "Quand un contenu est commercial, discutons du lien, des affirmations et des limites. Vous pouvez demander qui finance un contenu. Décider à ma place que chaque phrase a été achetée, c’est autre chose. La transparence se demande sur des faits.", "Le post affirme une limite aux accusations, mais la fermeté peut encore donner l’impression que tu repousses toute discussion sur les intérêts commerciaux.", ["noe", "On doit quand même pouvoir poser la question avant que le vendeur choisisse de tout raconter."], ["sam", "Oui. Une question sur un lien possible reste différente d’une certitude fabriquée."]),
    document: choice("Rendre tes principes explicites", "Tu décris ce que les lecteurs pourront examiner si un contenu est rémunéré.", "craft", "Si je publie un contenu rémunéré : une mention claire, un sujet identifiable et des affirmations que je peux défendre sans promesse inventée. Ça n’est pas un certificat d’indépendance. Ce sont des engagements que les lecteurs pourront comparer aux publications réelles.", "Les lecteurs disposent de critères pour juger tes contenus. Noé ne te donne pas un blanc-seing : il attend de voir si tu tiens ces limites quand elles te coûtent quelque chose.", ["jade", "Des engagements vérifiables, c’est plus utile qu’un grand « faites-moi confiance »."], ["visitor", "Je regarderai la publication elle-même, pas seulement le post où tu annonces tes principes."]),
    refocus: choice("Laisser les principes à leur juste place", "Tu termines sans réclamer un blanc-seing ni inventer de revenu.", "care", "Je laisse ces principes visibles. Ils ne remplacent ni une mention commerciale sur un contenu concerné ni le droit de me critiquer. Je ferme ce fil sans demander un certificat de confiance à l’avance.", "L’échange s’achève sans accord général. Aucun financement n’est annoncé et la confiance reste quelque chose à éprouver dans les publications futures.", ["ines", "On pourra relire ces principes quand il y aura un cas concret."], ["sam", "Et tu n’as pas besoin que Noé signe un quitus pour arrêter de répondre aujourd’hui."]),
  },
  consequences: {
    sharp: { body: "Ta réplique a ciblé le verdict de Noé mais laissé sa question sur l’intérêt du payeur en suspens. Le prochain post peut l’aborder ou prolonger le conflit.", lead: "J’ai répondu vivement au soupçon de parole achetée. Le sujet du financement mérite pourtant des limites explicites." },
    explain: { body: "Tu as reconnu le conflit d’intérêts possible et les limites de la transparence. Tu peux maintenant préciser tes engagements sans annoncer un partenariat imaginaire.", lead: "J’ai expliqué qu’une mention commerciale informe les lecteurs sans effacer tous les conflits possibles." },
    ignore: { body: "Tu n’as pas répondu à Noé. Le nouveau post peut poser tes principes sans raconter une explication ou une négociation qui n’a pas eu lieu.", lead: "Je n’ai pas répondu à l’accusation précédente. Je pose mes limites ici, et les lecteurs pourront juger si je les tiens." },
  },
});

export const KQ_SOCIAL_COMMUNITY_DEBATE_SCENARIOS = scenarios;
export const KQ_SOCIAL_COMMUNITY_DEBATE_NARRATIVES = narratives;
